/**
 * Unit tests for PiePlot.getMaximumExplodePercent().
 */
public class PiePlot_getMaximumExplodePercent_TriageGen1Test {

    private PiePlot piePlot;
    private PieDataset mockDataset;

    @Before
    public void setUp() {
        mockDataset = mock(PieDataset.class);
        piePlot = new PiePlot(mockDataset);
    }

    /**
     * Test case where the dataset is empty.
     * Expected: result should be 0.0.
     */
    @Test
    public void testGetMaximumExplodePercent_EmptyDataset() {
        List<Comparable> keys = new ArrayList<>();
        when(mockDataset.getKeys()).thenReturn(keys);

        double result = piePlot.getMaximumExplodePercent();

        assertEquals(0.0, result, 1e-10);
    }

    /**
     * Test case where dataset has keys but no explode percentages are set.
     * Expected: result should be 0.0.
     */
    @Test
    public void testGetMaximumExplodePercent_NoExplodeValues() {
        List<Comparable> keys = new ArrayList<>();
        keys.add("A");
        keys.add("B");
        when(mockDataset.getKeys()).thenReturn(keys);

        // By default, explode percentages are not set, so they return 0 or null internally via map lookup
        double result = piePlot.getMaximumExplodePercent();

        assertEquals(0.0, result, 1e-10);
    }

    /**
     * Test case where explode percentages are set for all keys.
     * Expected: result should be the maximum value.
     */
    @Test
    public void testGetMaximumExplodePercent_WithMultipleValues() {
        List<Comparable> keys = new ArrayList<>();
        keys.add("A");
        keys.add("B");
        keys.add("C");
        when(mockDataset.getKeys()).thenReturn(keys);

        piePlot.setExplodePercent("A", 0.1);
        piePlot.setExplodePercent("B", 0.5);
        piePlot.setExplodePercent("C", 0.3);

        double result = piePlot.getMaximumExplodePercent();

        assertEquals(0.5, result, 1e-10);
    }

    /**
     * Test case where some explode values are null (not set).
     * Expected: result should ignore nulls and find the max of existing values.
     */
    @Test
    public void testGetMaximumExplodePercent_WithNullValues() {
        List<Comparable> keys = new ArrayList<>();
        keys.add("A");
        keys.add("B");
        keys.add("C");
        when(mockDataset.getKeys()).thenReturn(keys);

        piePlot.setExplodePercent("A", 0.1);
        // "B" is left unset (null in the internal map)
        piePlot.setExplodePercent("C", 0.4);

        double result = piePlot.getMaximumExplodePercent();

        assertEquals(0.4, result, 1e-10);
    }

    /**
     * Test case with negative values (though unlikely in domain, tests logic).
     * Expected: result should be 0.0 because result is initialized to 0.0 and Math.max(0.0, negative) is 0.0.
     */
    @Test
    public void testGetMaximumExplodePercent_NegativeValues() {
        List<Comparable> keys = new ArrayList<>();
        keys.add("A");
        when(mockDataset.getKeys()).thenReturn(keys);

        piePlot.setExplodePercent("A", -0.5);

        double result = piePlot.getMaximumExplodePercent();

        assertEquals(0.0, result, 1e-10);
    }
}
